import React from 'react';
import { Box, Container, Typography, Grid, Button, Stack, TextField } from '@mui/material';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import ArrowForwardIcon from '@mui/icons-material/ArrowForward';

const Careers = () => {
  return (
    <Box sx={{ width: '100%' }}>
      {/* Top Section with Form */}
      <Box sx={{ backgroundColor: '#f5f5f5', py: 8 }}>
        <Container>
          <Grid container spacing={6} alignItems="center">
            <Grid item xs={12} md={6}>
              <Typography variant="h2" sx={{ fontWeight: 'bold', mb: 4, color: '#3D4459' }}>
                We are looking for <Box component="span" sx={{ color: '#239F7D' }}>You!</Box>
              </Typography>
              
              {/* Application Form */}
              <Box component="form" sx={{ '& .MuiTextField-root': { mb: 2 } }}>
                <Grid container spacing={2}>
                  <Grid item xs={12} sm={6}>
                    <TextField fullWidth placeholder="First Name" variant="outlined" />
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <TextField fullWidth placeholder="Last Name" variant="outlined" />
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <TextField fullWidth placeholder="Phone" variant="outlined" type="tel" />
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <TextField fullWidth placeholder="Email" variant="outlined" type="email" />
                  </Grid>
                  <Grid item xs={12}>
                    <TextField fullWidth placeholder="Zip" variant="outlined" />
                  </Grid>
                  <Grid item xs={12}>
                    <Button
                      variant="outlined"
                      component="label"
                      fullWidth
                      sx={{
                        borderColor: '#239F7D',
                        color: '#239F7D',
                        py: 1.5,
                        '&:hover': {
                          borderColor: '#1d8066',
                          backgroundColor: 'rgba(35, 159, 125, 0.04)',
                        },
                      }}
                    >
                      Upload your resume here
                      <input type="file" hidden accept=".pdf,.doc,.docx" />
                    </Button>
                  </Grid>
                  <Grid item xs={12}>
                    <Button
                      variant="contained"
                      fullWidth
                      sx={{
                        backgroundColor: '#239F7D',
                        color: '#fff',
                        py: 1.5,
                        fontWeight: 'bold',
                        '&:hover': {
                          backgroundColor: '#1d8066',
                        },
                      }}
                    >
                      Submit
                    </Button>
                  </Grid>
                </Grid>
              </Box>
            </Grid>

            <Grid item xs={12} md={6}>
              <Typography variant="body1" paragraph sx={{ fontSize: '1.05rem', lineHeight: 1.8, mb: 4 }}>
                We're looking to expand our team with insurance professionals who are self-starters. Are you looking to make real money helping real families? A career with aethon services may be right for you.
              </Typography>

              <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
                Why Choose SLS?
              </Typography>

              <Stack spacing={2}>
                {[
                  'New agents will receive the best training',
                  'Call leads on the phone',
                  'Join a strong company culture',
                  'Learn from experienced thought leaders',
                  'Get paid what you\'re worth'
                ].map((item, index) => (
                  <Box key={index} sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <CheckCircleIcon sx={{ color: '#239F7D', fontSize: 24 }} />
                    <Typography variant="body1" sx={{ fontSize: '1.05rem' }}>
                      {item}
                    </Typography>
                  </Box>
                ))}
              </Stack>
            </Grid>
          </Grid>
        </Container>
      </Box>

      {/* What We Offer Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#fff',
          py: 8,
          position: 'relative',
        }}
      >
        <Container>
          <Grid container spacing={6} alignItems="center">
            <Grid item xs={12} md={6}>
              <Typography variant="h3" sx={{ fontWeight: 'bold', mb: 3 }}>
                What We Offer You
              </Typography>
              <Typography variant="body1" paragraph sx={{ fontSize: '1.05rem', lineHeight: 1.8, mb: 4 }}>
                Our mission at ASLLC is to provide the best tools and resources available in the industry, to financially empower you to care for your family in ways you may never have thought imaginable. We'll offer you the best leads, sales environment, training, support, and compensation in the insurance industry while illuminating your pathway to retirement.
              </Typography>

              <Typography variant="h3" sx={{ fontWeight: 'bold', mb: 3, mt: 6 }}>
                The Final Expense Market Is Booming
              </Typography>
              <Typography variant="body1" paragraph sx={{ fontSize: '1.05rem', lineHeight: 1.8, mb: 2 }}>
                Whether you're interested in part-time or full-time work, you have the opportunity to set your own schedule. Take advantage of a booming market where tons of seniors nationwide are looking for a solution to covering their end-of-life expenses. Want to learn the business of selling insurance? We'll teach you all the ins and outs.
              </Typography>
              <Typography variant="body1" paragraph sx={{ fontSize: '1.05rem', lineHeight: 1.8, mb: 4 }}>
                To further explore our career opportunities, <a href="/contact/" style={{ color: '#333333ff', textDecoration: 'underline' }}>contact</a> us for a meeting. We look forward to chatting with you.
              </Typography>

              <Button
                variant="contained"
                endIcon={<ArrowForwardIcon />}
                href="#form"
                sx={{
                  backgroundColor: '#1d8066',
                  color: 'black',
                  fontWeight: 'bold',
                  '&:hover': {
                    backgroundColor: '#239F7D',
                  },
                }}
              >
                Get Started Today
              </Button>
            </Grid>

            <Grid item xs={12} md={6}>
              <Box
                component="img"
                src="https://senior-lifeservices.com/wp-content/uploads/2020/04/SLS-Marketing-Photo-17.jpg"
                alt="aethon services Average Funeral Cost"
                sx={{
                  width: '100%',
                  height: 'auto',
                  borderRadius: 2,
                  boxShadow: 3,
                }}
              />
            </Grid>
          </Grid>
        </Container>
      </Box>

      {/* Insurance Providers Section */}
      <Box sx={{ backgroundColor: '#fff', py: 8 }}>
        <Container>
          <Typography variant="h3" sx={{ fontWeight: 'bold', mb: 6, textAlign: 'center', color: '#3D4459' }}>
            We work with <Box component="span" sx={{ color: '#239F7D' }}>top insurance providers</Box>
          </Typography>
          
          <Grid container spacing={4} justifyContent="center" alignItems="center">
            {[
              { src: 'https://senior-lifeservices.com/wp-content/uploads/2020/03/mutual-of-omaha-gs.png', alt: 'Mutual of Omaha' },
              { src: 'https://senior-lifeservices.com/wp-content/uploads/2020/03/royal-neighbors-of-america-gs.png', alt: 'Royal Neighbors of America' },
              { src: 'https://senior-lifeservices.com/wp-content/uploads/2020/03/aig.png', alt: 'AIG' },
              { src: 'https://senior-lifeservices.com/wp-content/uploads/2020/03/gerber.png', alt: 'Gerber' },
              { src: 'https://senior-lifeservices.com/wp-content/uploads/2020/03/transamerica-292x124-1.png', alt: 'Transamerica' },
              { src: 'https://senior-lifeservices.com/wp-content/uploads/2020/03/aetna.png', alt: 'Aetna' },
            ].map((logo, index) => (
              <Grid item xs={6} sm={4} md={2} key={index}>
                <Box
                  component="img"
                  src={logo.src}
                  alt={logo.alt}
                  sx={{
                    width: '100%',
                    height: 'auto',
                    filter: 'grayscale(100%)',
                    opacity: 0.7,
                    transition: 'all 0.3s',
                    '&:hover': {
                      filter: 'grayscale(0%)',
                      opacity: 1,
                    },
                  }}
                />
              </Grid>
            ))}
          </Grid>
        </Container>
      </Box>
    </Box>
  );
};

export default Careers;