import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button, Stack } from '@mui/material';
import ArrowForwardIcon from '@mui/icons-material/ArrowForward';

const HighRiskLifeInsurance = () => {
  return (
    <Box sx={{ width: '100%' }}>
      {/* Main Content */}
      <Container sx={{ py: 6 }}>
        <Grid container spacing={4}>
          <Grid item xs={12}>
            {/* Hero Section */}
            <Card sx={{ boxShadow: 3, mb: 4 }}>
              <CardContent sx={{ p: { xs: 3, md: 4 } }}>
                <Grid container spacing={4} alignItems="center">
                  <Grid item xs={12} md={6}>
                    <Typography variant="h3" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
                      High-risk life insurance
                    </Typography>
                    <Stack spacing={2}>
                      <Typography variant="body1" sx={{ fontSize: '1.05rem', lineHeight: 1.8 }}>
                        Many seniors suffer from chronic diseases or other impairments that cause them to be in the market for high-risk life insurance.
                      </Typography>
                      <Typography variant="body1" sx={{ fontSize: '1.05rem', lineHeight: 1.8 }}>
                        You may be one of these people who find it impossible to get life insurance. But high-risk life insurance, or guaranteed issue life insurance, is your solution!
                      </Typography>
                    </Stack>
                  </Grid>
                  <Grid item xs={12} md={6}>
                    <Box
                      component="img"
                      src="https://senior-lifeservices.com/wp-content/uploads/2020/04/SLS-Marketing-Photo-33-1024x683.jpg"
                      alt="aethon services final expense insurance"
                      sx={{
                        width: '100%',
                        height: 'auto',
                        borderRadius: 2,
                      }}
                    />
                  </Grid>
                </Grid>
              </CardContent>
            </Card>

            {/* What is high-risk life insurance */}
            <Card sx={{ boxShadow: 3, mb: 4 }}>
              <CardContent sx={{ p: { xs: 3, md: 4 } }}>
                <Stack spacing={3}>
                  <Typography variant="h4" sx={{ fontWeight: 'bold', color: '#0170B9' }}>
                    What is high-risk life insurance?
                  </Typography>
                  <Typography variant="body1" sx={{ fontSize: '1.05rem', lineHeight: 1.8 }}>
                    <a href="/burial-insurance/guaranteed/" target="_blank" rel="noreferrer">Guaranteed life insurance</a> is the policy that was created for people who normally can't get coverage because of their "high risk."
                  </Typography>
                  <Typography variant="body1" sx={{ fontSize: '1.05rem', lineHeight: 1.8 }}>
                    There is no health underwriting and an extremely brief application process.
                  </Typography>
                  <Box>
                    <Button
                      variant="contained"
                      endIcon={<ArrowForwardIcon />}
                      href="/contact/"
                      sx={{
                        backgroundColor: '#239F7D',
                        color: '#fff',
                        fontWeight: 'bold',
                        px: 4,
                        py: 1.5,
                        '&:hover': {
                          backgroundColor: '#1d8066',
                        },
                      }}
                    >
                      high-risk life insurance quotes
                    </Button>
                  </Box>
                </Stack>
              </CardContent>
            </Card>

            {/* Benefits of guaranteed life insurance */}
            <Card sx={{ boxShadow: 3, mb: 4 }}>
              <CardContent sx={{ p: { xs: 3, md: 4 } }}>
                <Stack spacing={3}>
                  <Typography variant="h4" sx={{ fontWeight: 'bold', color: '#0170B9' }}>
                    Benefits of guaranteed life insurance
                  </Typography>
                  <Typography variant="body1" sx={{ fontSize: '1.05rem', lineHeight: 1.8 }}>
                    Other than the fact virtually everyone is guaranteed acceptance and the fact that there is no medical exam, there are other benefits to this policy:
                  </Typography>
                  <Box component="ul" sx={{ fontSize: '1.05rem', lineHeight: 1.8, pl: 3 }}>
                    <Box component="li" sx={{ mb: 1 }}>
                      The premium never goes up
                    </Box>
                    <Box component="li" sx={{ mb: 1 }}>
                      The benefit never goes down
                    </Box>
                    <Box component="li" sx={{ mb: 1 }}>
                      Coverage does not expire as long as premiums are paid
                    </Box>
                    <Box component="li" sx={{ mb: 1 }}>
                      No medical exam
                    </Box>
                    <Box component="li">
                      No health questions
                    </Box>
                  </Box>
                  <Box
                    component="img"
                    src="https://senior-lifeservices.com/wp-content/uploads/2020/04/SLS-High-risk-life-insurance.jpg"
                    alt="high risk life insurance"
                    sx={{
                      width: '100%',
                      height: 'auto',
                      borderRadius: 2,
                      mt: 2,
                    }}
                  />
                </Stack>
              </CardContent>
            </Card>

            {/* Is there a waiting period + What does guaranteed issue cost */}
            <Card sx={{ boxShadow: 3, mb: 4 }}>
              <CardContent sx={{ p: { xs: 3, md: 4 } }}>
                <Stack spacing={3}>
                  <Typography variant="h4" sx={{ fontWeight: 'bold', color: '#0170B9' }}>
                    Is there a waiting period?
                  </Typography>
                  <Typography variant="body1" sx={{ fontSize: '1.05rem', lineHeight: 1.8 }}>
                    There is at least a two-year waiting period with this type of insurance.
                  </Typography>
                  <Typography variant="body1" sx={{ fontSize: '1.05rem', lineHeight: 1.8 }}>
                    This means until the "waiting period" is over your benefit will either be on a graded scale or at least the amount of premium you paid in.
                  </Typography>
                  <Typography variant="body1" sx={{ fontSize: '1.05rem', lineHeight: 1.8 }}>
                    However, depending on your health issues, we can sometimes find a company who will offer you a simplified issue policy.
                  </Typography>
                  <Typography variant="body1" sx={{ fontSize: '1.05rem', lineHeight: 1.8 }}>
                    And some companies offer a rider that not only will pay out the full death benefit if your death was caused by an accident in that time period, but pay out double.
                  </Typography>
                  <Box>
                    <Button
                      variant="contained"
                      endIcon={<ArrowForwardIcon />}
                      href="/contact/"
                      sx={{
                        backgroundColor: '#239F7D',
                        color: '#fff',
                        fontWeight: 'bold',
                        px: 4,
                        py: 1.5,
                        '&:hover': {
                          backgroundColor: '#1d8066',
                        },
                      }}
                    >
                      Find affordable high-risk life insurance
                    </Button>
                  </Box>

                  <Typography variant="h4" sx={{ fontWeight: 'bold', color: '#0170B9', mt: 2 }}>
                    What does guaranteed issue life insurance cost?
                  </Typography>
                  <Typography variant="body1" sx={{ fontSize: '1.05rem', lineHeight: 1.8 }}>
                    Premiums are higher for this type of insurance because of the risk associated with the people who need it.
                  </Typography>
                  <Typography variant="body1" sx={{ fontSize: '1.05rem', lineHeight: 1.8 }}>
                    However, the trade-off is it is guaranteed acceptance, coverage does not expire, and premiums do not increase. This is meant as a sort of "last-resort" policy when you cannot find coverage through other means.
                  </Typography>
                  <Typography variant="body1" sx={{ fontSize: '1.05rem', lineHeight: 1.8 }}>
                    And you certainly don't want to have to pass off your final expenses to your surviving family.
                  </Typography>
                </Stack>
              </CardContent>
            </Card>

            {/* How do I apply */}
            <Card sx={{ boxShadow: 3 }}>
              <CardContent sx={{ p: { xs: 3, md: 4 } }}>
                <Stack spacing={3}>
                  <Typography variant="h4" sx={{ fontWeight: 'bold', color: '#0170B9' }}>
                    How do I apply?
                  </Typography>
                  <Typography variant="body1" sx={{ fontSize: '1.05rem', lineHeight: 1.8 }}>
                    We can help you through this process and find you the best solutions for your life insurance needs. Click below to get rates from multiple insurance companies so you can be sure to get the best deal available.
                  </Typography>
                </Stack>
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      </Container>
    </Box>
  );
};

export default HighRiskLifeInsurance;
