import React, { useState } from 'react';
import emailjs from '@emailjs/browser';
import { Box, Container, Typography, Button, Grid, TextField, Stack, Card, CardContent } from '@mui/material';
import CheckIcon from '@mui/icons-material/Check';
import PhoneIcon from '@mui/icons-material/Phone';
import LocationOnIcon from '@mui/icons-material/LocationOn';
import ArrowForwardIcon from '@mui/icons-material/ArrowForward';
import image from '../assets/SLS-Marketing-Photo-39-1024x683.png';
const Contact = () => {
    const [formData, setFormData] = useState({
      fullName: '',
      phone: '',
      email: '',
      dob: '',
      zipCode: '',
      message: ''
    });
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [submitStatus, setSubmitStatus] = useState({ type: '', message: '' });
    console.log('Environment Variables:', {
      SERVICE_ID: process.env.REACT_APP_SERVICE_ID,
      TEMPLATE_ID: process.env.REACT_APP_TEMPLATE_ID,
      PUBLIC_KEY: process.env.REACT_APP_PUBLIC_KEY
    });
    const EMAILJS_SERVICE_ID = process.env.REACT_APP_SERVICE_ID;
    const EMAILJS_TEMPLATE_ID = process.env.REACT_APP_TEMPLATE_ID;
    const EMAILJS_PUBLIC_KEY = process.env.REACT_APP_PUBLIC_KEY;
  
    const handleChange = (e) => {
      setFormData({
        ...formData,
        [e.target.name]: e.target.value
      });
    };
  
  
  const benefits = [
    'We shop 150+ carriers for you',
    'No waiting period plans available',
    'BBB approved company with a+ rating',
    'Get the lowest price possible',
    'Quick quotes'
  ];

  
  const handleSubmit = async () => {
    setIsSubmitting(true);
    setSubmitStatus({ type: '', message: '' });

    // Validate form
    if (!formData.fullName || !formData.phone || !formData.email) {
      setSubmitStatus({
        type: 'error',
        message: 'Please fill in all required fields'
      });
      setIsSubmitting(false);
      return;
    }

    try {
      // Send email using EmailJS
      const result = await emailjs.send(
        EMAILJS_SERVICE_ID,
        EMAILJS_TEMPLATE_ID,
        {
          from_name: formData.fullName,
          phone: formData.phone,
          email: formData.email,
          dob: formData.dob,
          zip_code: formData.zipCode,
          message: formData.message,
          submission_date: new Date().toLocaleString(),
        },
        EMAILJS_PUBLIC_KEY
      );

      console.log('Email sent successfully:', result);
      
      setSubmitStatus({
        type: 'success',
        message: 'Message request sent successfully! We\'ll get back to you soon.'
      });

      // Reset form
      setFormData({
        fullName: '',
        phone: '',
        email: '',
        dob: '',
        zipCode: '',
        message: ''
      });
    } catch (error) {
      console.error('Failed to send email:', error);
      setSubmitStatus({
        type: 'error',
        message: 'Failed to send request. Please try again or contact us directly.'
      });
    } finally {
      setIsSubmitting(false);
    }
  };


  return (
    <Box sx={{ width: '100%' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 10,
          textAlign: 'center',
          position: 'relative',
          overflow: 'hidden',
          '&::before': {
            content: '""',
            position: 'absolute',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: 'radial-gradient(circle at 20% 50%, rgba(255,255,255,0.1) 0%, transparent 50%)',
            pointerEvents: 'none',
          }
        }}
      >
        <Container sx={{ position: 'relative', zIndex: 1 }}>
          <Typography 
            variant="h1" 
            sx={{ 
              fontWeight: 900,
              mb: 2,
              fontSize: { xs: '2.5rem', sm: '3.5rem', md: '4rem' },
              letterSpacing: '-1px',
              background: 'linear-gradient(135deg, #FFFFFF 0%, #FFFACD 50%, #FFFFFF 100%)',
              backgroundClip: 'text',
              WebkitBackgroundClip: 'text',
              WebkitTextFillColor: 'transparent',
              textShadow: '2px 2px 4px rgba(0,0,0,0.2)',
              filter: 'drop-shadow(2px 2px 4px rgba(0,0,0,0.15))',
            }}
          >
            What Can We Do For You?
          </Typography>
          <Typography 
            variant="h5" 
            sx={{ 
              fontWeight: 400,
              fontSize: { xs: '1rem', md: '1.25rem' },
              color: '#FFFACD',
              mb: 1,
              letterSpacing: '1px',
              fontStyle: 'italic',
            }}
          >
            Protect Your Family, Plan Your Future
          </Typography>
          <Box
            sx={{
              height: '3px',
              width: '60px',
              background: 'linear-gradient(90deg, #FFFACD 0%, transparent 100%)',
              margin: '0 auto',
              mt: 2,
            }}
          />
        </Container>
      </Box>

      {/* Main Content */}
      <Container sx={{ py: 6 }}>
        <Grid container spacing={4}>
          {/* Benefits and Form Section */}
          <Grid item xs={12}>
            <Card sx={{ boxShadow: 3, backgroundColor: '#f5f5f5' }}>
              <CardContent sx={{ p: { xs: 3, md: 4 } }}>
                {/* Benefits List */}
                <Stack 
                  direction={{ xs: 'column', sm: 'row' }} 
                  spacing={2} 
                  sx={{ 
                    mb: 4, 
                    flexWrap: 'wrap',
                    justifyContent: 'center',
                    alignItems: 'center'
                  }}
                >
                  {benefits.map((benefit, index) => (
                    <Box 
                      key={index} 
                      sx={{ 
                        display: 'flex', 
                        alignItems: 'center', 
                        gap: 1 
                      }}
                    >
                      <CheckIcon sx={{ color: '#239F7D', fontSize: 20 }} />
                      <Typography variant="body2" sx={{ fontSize: '0.95rem' }}>
                        {benefit}
                      </Typography>
                    </Box>
                  ))}
                </Stack>

                {/* Contact Form */}
                      <Box
  sx={{
    mx: 'auto',
    backgroundColor: '#FFFFFF',
    p: 4,
    borderRadius: '15px',
    boxShadow: '0px 0px 20px rgba(0, 0, 0, 0.05)',
  }}
>
  <Grid container spacing={2}>
    <Grid item xs={12}>
      <TextField
        fullWidth
        label="Full Name"
        placeholder="Full Name"
        variant="outlined"
        name="fullName"
        value={formData.fullName}
        onChange={handleChange}
        required
      />
    </Grid>
    
    <Grid item xs={12} sm={6}>
      <TextField
        fullWidth
        label="Phone"
        placeholder="Phone"
        variant="outlined"
        name="phone"
        value={formData.phone}
        onChange={handleChange}
        required
      />
    </Grid>
    
    <Grid item xs={12} sm={6}>
      <TextField
        fullWidth
        label="Email"
        placeholder="Email"
        type="email"
        variant="outlined"
        name="email"
        value={formData.email}
        onChange={handleChange}
        required
      />
    </Grid>
    
    <Grid item xs={12} sm={6}>
      <TextField
        fullWidth
        label="Date of Birth"
        type="date"
        variant="outlined"
        name="dob"
        value={formData.dob}
        onChange={handleChange}
        InputLabelProps={{ shrink: true }}
      />
    </Grid>
    
    <Grid item xs={12} sm={6}>
      <TextField
        fullWidth
        label="Zip Code"
        placeholder="Zip Code"
        variant="outlined"
        name="zipCode"
        value={formData.zipCode}
        onChange={handleChange}
      />
    </Grid>
    
    <Grid item xs={12}>
      <TextField
        fullWidth
        label="Message"
        placeholder="Tell us about your requirements..."
        variant="outlined"
        name="message"
        value={formData.message}
        onChange={handleChange}
        multiline
        rows={4}
      />
    </Grid>

    {/* Status Message */}
    {submitStatus.message && (
      <Grid item xs={12}>
        <Box
          sx={{
            p: 2,
            borderRadius: '8px',
            backgroundColor: submitStatus.type === 'success' ? '#d4edda' : '#f8d7da',
            color: submitStatus.type === 'success' ? '#155724' : '#721c24',
            border: submitStatus.type === 'success' ? '1px solid #c3e6cb' : '1px solid #f5c6cb',
          }}
        >
          {submitStatus.message}
        </Box>
      </Grid>
    )}
    
    <Grid item xs={12}>
      <Box display="flex" >
        <Button
          fullWidth
          variant="contained"
          onClick={handleSubmit}
          disabled={isSubmitting}
          sx={{
            maxWidth: '20%',
            backgroundColor: '#239F7D',
            '&:hover': {
              backgroundColor: '#006F51',
            },
            '&:disabled': {
              backgroundColor: '#cccccc',
            },
          }}
        >
          {isSubmitting ? 'Sending...' : 'Send a Message'}
        </Button>
      </Box>
    </Grid>
  </Grid>
</Box>
              </CardContent>
            </Card>
          </Grid>

          {/* Contact Information Section */}
          <Grid item xs={12}>
            <Card sx={{ boxShadow: 3 }}>
              <CardContent sx={{ p: { xs: 3, md: 4 } }}>
                <Grid container spacing={4} alignItems="center">
                  <Grid item xs={12} md={6}>
                    <Typography 
                      variant="h4" 
                      sx={{ 
                        fontWeight: 'bold', 
                        mb: 3, 
                        color: '#0170B9'
                      }}
                    >
                      Contact
                    </Typography>
                    
                    <Typography 
                      variant="body1" 
                      paragraph 
                      sx={{ fontSize: '1.05rem', lineHeight: 1.8, mb: 3 }}
                    >
                      If you need help deciding on an insurance plan, we can help you find the lowest quotes or the highest amount of coverage available in your area.
                    </Typography>

                    <Stack spacing={2} sx={{ mb: 4 }}>
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                        <PhoneIcon sx={{ color: '#239F7D', fontSize: 24 }} />
                        <Typography 
                          component="a" 
                          href="tel:888-241-5309"
                          sx={{ 
                            fontSize: '1.1rem',
                            color: '#3D4459',
                            textDecoration: 'none',
                            '&:hover': { color: '#0170B9' }
                          }}
                        >
                          888-241-5309
                        </Typography>
                      </Box>
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                        <LocationOnIcon sx={{ color: '#239F7D', fontSize: 24 }} />
                        <Typography sx={{ fontSize: '1.05rem', color: '#3D4459' }}>
                          85 Rose Ct, Albany NY 12209
                        </Typography>
                      </Box>
                    </Stack>

                    <Button
                      variant="contained"
                      startIcon={<PhoneIcon />}
                      href="tel:888-241-5390"
                      sx={{
                        backgroundColor: '#239F7D',
                        color: '#fff',
                        fontWeight: 'bold',
                        px: 4,
                        py: 1.5,
                        '&:hover': {
                          backgroundColor: '#1d8066'
                        }
                      }}
                    >
                      888-241-5309
                    </Button>
                  </Grid>

                  <Grid item xs={12} md={6}>
                    <Box
                      component="img"
                      src={image}
                      alt="aethon services burial insurance"
                      sx={{
                        width: '100%',
                        height: 'auto',
                        borderRadius: 2,
                        boxShadow: 3
                      }}
                    />
                  </Grid>
                </Grid>
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      </Container>
    </Box>
  );
};

export default Contact;
