import React, { useState } from 'react';
import {
  AppBar,
  Toolbar,
  Container,
  Button,
  Box,
  Drawer,
  IconButton,
  List,
  ListItem,
  ListItemText,
  useMediaQuery,
  useTheme,
  Menu,
  MenuItem,
  Collapse,
  Paper,
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import MenuIcon from '@mui/icons-material/Menu';
import CloseIcon from '@mui/icons-material/Close';
import KeyboardArrowDownIcon from '@mui/icons-material/KeyboardArrowDown';
import logo from '../assets/logo.png';

const Navbar = () => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [expandedMenu, setExpandedMenu] = useState(null);

  // Dropdown menu anchors for desktop
  const [anchorEl, setAnchorEl] = useState({
    burialInsurance: null,
    costOfBurial: null,
    highRisk: null,
    about: null,
    finalExpense: null,
  });

  // const navLinks = [
  //   { label: 'Home', path: '/' },
  //   { label: 'Contact', path: '/contact' },
  // ];

  const burialInsuranceMenu = [
    {label: 'Burial Insurance', path: '/burial-insurance' },
    { label: 'What is Burial Insurance?', path: '/burial-insurance/what-is' },
    { label: 'Burial Insurance No Exam', path: '/burial-insurance/no-exam' },
    { label: 'Types of Burial Insurance', path: '/burial-insurance/types' },
    { label: 'Simplified Issue Life Insurance', path: '/burial-insurance/simplified-issue' },
    { label: 'Guaranteed Life Insurance', path: '/burial-insurance/guaranteed' },
    { label: 'Best Burial Insurance Companies', path: '/burial-insurance/best-companies' },
    { label: 'Burial Insurance Quotes', path: '/burial-insurance/quotes' },
  ];

  const costOfBurialMenu = [
    { label: 'Cost of Burial Insurance', path: '/cost-of-burial' },
    { label: 'How Much Does It Cost?', path: '/cost-of-burial/how-much' },
    { label: 'Average Funeral Cost', path: '/cost-of-burial/average-cost' },
    { label: 'Cremation Costs', path: '/cost-of-burial/cremation' },
    { label: 'Prepaid Burial Plans', path: '/cost-of-burial/prepaid' },
    { label: 'Is Burial Insurance Worth It?', path: '/cost-of-burial/worth-it' },
    { label: 'Affordable Insurance for Seniors', path: '/cost-of-burial/seniors' },
  ];

  const highRiskMenu = [
    { label: 'High-Risk Life Insurance', path: '/high-risk' },
    { label: 'Burial Insurance for Cancer Patients', path: '/high-risk/cancer' },
    { label: 'Burial Insurance for Diabetics', path: '/high-risk/diabetics' },
    { label: 'Life Insurance for Seniors Over 80', path: '/high-risk/seniors-over-80' },
    { label: 'Burial Insurance for Medicaid Recipients', path: '/high-risk/medicaid' },
    { label: 'No Waiting Period Burial Insurance', path: '/high-risk/no-waiting-period' },
    { label: 'Burial Insurance for Smokers', path: '/high-risk/smokers' },
  ];

  const aboutMenu = [
    { label: 'About Us', path: '/about' },
    // { label: 'Blog', path: '/about/blog' },
    // { label: 'Careers', path: '/about/careers' },
    // { label: 'Giving Back', path: '/about/giving-back' },
  ];

  const statesMenu = [
    { label: 'Final Expense by State', path: '/final-expense/final-expense-by-state' },
    { label: 'Alabama', path: '/final-expense/alabama' },
    { label: 'Alaska', path: '/final-expense/alaska' },
    { label: 'Arizona', path: '/final-expense/arizona' },
    { label: 'Arkansas', path: '/final-expense/arkansas' },
    { label: 'California', path: '/final-expense/california' },
    { label: 'Colorado', path: '/final-expense/colorado' },
    { label: 'Connecticut', path: '/final-expense/connecticut' },
    { label: 'Delaware', path: '/final-expense/delaware' },
    { label: 'Florida', path: '/final-expense/florida' },
    { label: 'Georgia', path: '/final-expense/georgia' },
    { label: 'Hawaii', path: '/final-expense/hawaii' },
    { label: 'Idaho', path: '/final-expense/idaho' },
    { label: 'Illinois', path: '/final-expense/illinois' },
    { label: 'Indiana', path: '/final-expense/indiana' },
    { label: 'Iowa', path: '/final-expense/iowa' },
    { label: 'Kansas', path: '/final-expense/kansas' },
    { label: 'Kentucky', path: '/final-expense/kentucky' },
    { label: 'Louisiana', path: '/final-expense/louisiana' },
    { label: 'Maine', path: '/final-expense/maine' },
    { label: 'Maryland', path: '/final-expense/maryland' },
    { label: 'Massachusetts', path: '/final-expense/massachusetts' },
    { label: 'Michigan', path: '/final-expense/michigan' },
    { label: 'Minnesota', path: '/final-expense/minnesota' },
    { label: 'Mississippi', path: '/final-expense/mississippi' },
    { label: 'Missouri', path: '/final-expense/missouri' },
    { label: 'Montana', path: '/final-expense/montana' },
    { label: 'Nebraska', path: '/final-expense/nebraska' },
    { label: 'Nevada', path: '/final-expense/nevada' },
    { label: 'New Hampshire', path: '/final-expense/new-hampshire' },
    { label: 'New Jersey', path: '/final-expense/new-jersey' },
    { label: 'New Mexico', path: '/final-expense/new-mexico' },
    { label: 'New York', path: '/final-expense/new-york' },
    { label: 'North Carolina', path: '/final-expense/north-carolina' },
    { label: 'North Dakota', path: '/final-expense/north-dakota' },
    { label: 'Ohio', path: '/final-expense/ohio' },
    { label: 'Oklahoma', path: '/final-expense/oklahoma' },
    { label: 'Oregon', path: '/final-expense/oregon' },
    { label: 'Pennsylvania', path: '/final-expense/pennsylvania' },
    { label: 'Rhode Island', path: '/final-expense/rhode-island' },
    { label: 'South Carolina', path: '/final-expense/south-carolina' },
    { label: 'South Dakota', path: '/final-expense/south-dakota' },
    { label: 'Tennessee', path: '/final-expense/tennessee' },
    { label: 'Texas', path: '/final-expense/texas' },
    { label: 'Utah', path: '/final-expense/utah' },
    { label: 'Vermont', path: '/final-expense/vermont' },
    { label: 'Virginia', path: '/final-expense/virginia' },
    { label: 'Washington', path: '/final-expense/washington' },
    { label: 'West Virginia', path: '/final-expense/west-virginia' },
    { label: 'Wisconsin', path: '/final-expense/wisconsin' },
    { label: 'Wyoming', path: '/final-expense/wyoming' },
  ];

  const handleDrawerToggle = () => {
    setDrawerOpen(!drawerOpen);
  };

  const handleMenuOpen = (menuName, event) => {
    event.preventDefault();
    setAnchorEl(prev => ({
      ...prev,
      [menuName]: event.currentTarget,
    }));
  };

  const handleMenuClose = (menuName) => {
    setAnchorEl(prev => ({
      ...prev,
      [menuName]: null,
    }));
  };

  const toggleMobileMenu = (menuName) => {
    setExpandedMenu(expandedMenu === menuName ? null : menuName);
  };

  const drawer = (
    <Box
      sx={{
        width: 300,
        backgroundColor: 'linear-gradient(180deg, #0170B9 0%, #239F7D 100%)',
        height: '100%',
        color: '#FFFFFF',
        overflowY: 'auto',
      }}
    >
      <Box sx={{ display: 'flex', justifyContent: 'flex-end', p: 2 }}>
        <IconButton
          onClick={handleDrawerToggle}
          sx={{ color: '#FFFFFF' }}
        >
          <CloseIcon />
        </IconButton>
      </Box>
      <List>
        {/* {navLinks.map((link, index) => (
          <ListItem
            key={index}
            component={RouterLink}
            to={link.path}
            onClick={handleDrawerToggle}
            sx={{
              fontWeight: '600',
              fontSize: '16px',
              '&:hover': {
                backgroundColor: 'rgba(255, 255, 255, 0.15)',
              },
            }}
          >
            <ListItemText primary={link.label} sx={{ color: '#FFFFFF' }} />
          </ListItem>
        ))} */}

        {/* Burial Insurance Menu */}
        <ListItem
          button
          onClick={() => toggleMobileMenu('burialInsurance')}
          sx={{ 
            backgroundColor: 'rgba(255, 255, 255, 0.12)',
            fontWeight: '700',
            fontSize: '15px',
            margin: '8px 0',
          }}
        >
          <ListItemText primary="Burial Insurance" sx={{ color: '#FFFFFF' }} />
        </ListItem>
        <Collapse in={expandedMenu === 'burialInsurance'} timeout="auto" unmountOnExit>
          <List component="div" disablePadding>
            {burialInsuranceMenu.map((item, idx) => (
              <ListItem
                key={idx}
                component={RouterLink}
                to={item.path}
                onClick={handleDrawerToggle}
                sx={{ 
                  pl: 4, 
                  fontSize: '13px',
                  fontWeight: '500',
                  '&:hover': { backgroundColor: 'rgba(255, 255, 255, 0.15)' } 
                }}
              >
                <ListItemText primary={item.label} sx={{ color: '#FFFFFF' }} />
              </ListItem>
            ))}
          </List>
        </Collapse>

        {/* Cost of Burial Menu */}
        <ListItem
          button
          onClick={() => toggleMobileMenu('costOfBurial')}
          sx={{ 
            backgroundColor: 'rgba(255, 255, 255, 0.12)',
            fontWeight: '700',
            fontSize: '15px',
            margin: '8px 0',
          }}
        >
          <ListItemText primary="Cost of Burial Insurance" sx={{ color: '#FFFFFF' }} />
        </ListItem>
        <Collapse in={expandedMenu === 'costOfBurial'} timeout="auto" unmountOnExit>
          <List component="div" disablePadding>
            {costOfBurialMenu.map((item, idx) => (
              <ListItem
                key={idx}
                component={RouterLink}
                to={item.path}
                onClick={handleDrawerToggle}
                sx={{ 
                  pl: 4, 
                  fontSize: '13px',
                  fontWeight: '500',
                  '&:hover': { backgroundColor: 'rgba(255, 255, 255, 0.15)' } 
                }}
              >
                <ListItemText primary={item.label} sx={{ color: '#FFFFFF' }} />
              </ListItem>
            ))}
          </List>
        </Collapse>

        {/* High-Risk Menu */}
        <ListItem
          button
          onClick={() => toggleMobileMenu('highRisk')}
          sx={{ 
            backgroundColor: 'rgba(255, 255, 255, 0.12)',
            fontWeight: '700',
            fontSize: '15px',
            margin: '8px 0',
          }}
        >
          <ListItemText primary="High-Risk Life Insurance" sx={{ color: '#FFFFFF' }} />
        </ListItem>
        <Collapse in={expandedMenu === 'highRisk'} timeout="auto" unmountOnExit>
          <List component="div" disablePadding>
            {highRiskMenu.map((item, idx) => (
              <ListItem
                key={idx}
                component={RouterLink}
                to={item.path}
                onClick={handleDrawerToggle}
                sx={{ 
                  pl: 4, 
                  fontSize: '13px',
                  fontWeight: '500',
                  '&:hover': { backgroundColor: 'rgba(255, 255, 255, 0.15)' } 
                }}
              >
                <ListItemText primary={item.label} sx={{ color: '#FFFFFF' }} />
              </ListItem>
            ))}
          </List>
        </Collapse>

        {/* About Menu */}
        <ListItem
          button
          onClick={() => toggleMobileMenu('about')}
          sx={{ 
            backgroundColor: 'rgba(255, 255, 255, 0.12)',
            fontWeight: '700',
            fontSize: '15px',
            margin: '8px 0',
          }}
        >
          <ListItemText primary="About" sx={{ color: '#FFFFFF' }} />
        </ListItem>
        <Collapse in={expandedMenu === 'about'} timeout="auto" unmountOnExit>
          <List component="div" disablePadding>
            {aboutMenu.map((item, idx) => (
              <ListItem
                key={idx}
                component={RouterLink}
                to={item.path}
                onClick={handleDrawerToggle}
                sx={{ 
                  pl: 4, 
                  fontSize: '13px',
                  fontWeight: '500',
                  '&:hover': { backgroundColor: 'rgba(255, 255, 255, 0.15)' } 
                }}
              >
                <ListItemText primary={item.label} sx={{ color: '#FFFFFF' }} />
              </ListItem>
            ))}
          </List>
        </Collapse>

        {/* Final Expense Menu */}
        <ListItem
          button
          onClick={() => toggleMobileMenu('finalExpense')}
          sx={{ 
            backgroundColor: 'rgba(255, 255, 255, 0.12)',
            fontWeight: '700',
            fontSize: '15px',
            margin: '8px 0',
          }}
        >
          <ListItemText primary="Final Expense by State" sx={{ color: '#FFFFFF' }} />
        </ListItem>
        <Collapse in={expandedMenu === 'finalExpense'} timeout="auto" unmountOnExit>
          <List component="div" disablePadding sx={{ maxHeight: '300px', overflowY: 'auto' }}>
            {statesMenu.map((item, idx) => (
              <ListItem
                key={idx}
                component={RouterLink}
                to={item.path}
                onClick={handleDrawerToggle}
                sx={{ 
                  pl: 4, 
                  fontSize: '12px',
                  fontWeight: '500',
                  '&:hover': { backgroundColor: 'rgba(255, 255, 255, 0.15)' } 
                }}
              >
                <ListItemText primary={item.label} sx={{ color: '#FFFFFF' }} />
              </ListItem>
            ))}
          </List>
        </Collapse>
        <ListItem
          component={RouterLink}
          to="/contact"
          onClick={handleDrawerToggle}
          sx={{
            fontWeight: '700',
            fontSize: '15px',
            margin: '8px 0',
            '&:hover': { backgroundColor: 'rgba(255, 255, 255, 0.12)' },
          }}
        >
          <ListItemText primary="Contact Us" sx={{ color: '#FFFFFF' }} />
        </ListItem>
      </List>
    </Box>
  );

  return (
    <AppBar 
      position="sticky" 
      sx={{ 
        backgroundColor: '#FFFFFF',
        boxShadow: '0 2px 8px rgba(0, 0, 0, 0.1)',
      }}
    >
      <Container maxWidth="lg">
        <Toolbar
          sx={{
            display: 'flex',
            justifyContent: 'space-between',
            padding: '8px 0 !important',
            minHeight: '75px',
          }}
        >
          {/* Logo */}
          <RouterLink
            to="/"
            style={{
              textDecoration: 'none',
              display: 'flex',
              alignItems: 'center',
              gap: '10px',
            }}
          >
            <Box
              component="img"
              src={logo}
              alt="Aethon Services logo"
              sx={{
                width: 50,
                height: 50,
                borderRadius: '8px',
                display: 'block',
                objectFit: 'contain',
                boxShadow: '0 2px 8px rgba(1, 112, 185, 0.3)',
              }}
            />
            <Box sx={{ display: { xs: 'none', sm: 'block' } }}>
              <Box sx={{ fontSize: '18px', fontWeight: '700', color: '#0170B9' }}>
                Aethon Services
              </Box>
              <Box sx={{ fontSize: '11px', color: '#7A7A7A', marginTop: '-2px' }}>
                Quality Insurance Solutions
              </Box>
            </Box>
          </RouterLink>

          {/* Desktop Navigation */}
          {!isMobile && (
            <Box sx={{ display: 'flex', gap: 0.5, alignItems: 'center' }}>
              {/* {navLinks.map((link, index) => (
                <Button
                  key={index}
                  component={RouterLink}
                  to={link.path}
                  sx={{
                    color: '#4B4F58',
                    fontWeight: '600',
                    fontSize: '14px',
                    padding: '8px 14px',
                    position: 'relative',
                    transition: 'all 0.3s ease',
                    '&:hover': {
                      color: '#0170B9',
                      backgroundColor: 'rgba(1, 112, 185, 0.08)',
                      borderRadius: '4px',
                    },
                    '&::after': {
                      content: '""',
                      position: 'absolute',
                      bottom: '0',
                      left: '50%',
                      width: '0',
                      height: '3px',
                      backgroundColor: '#0170B9',
                      transform: 'translateX(-50%)',
                      transition: 'width 0.3s ease',
                    },
                    '&:hover::after': {
                      width: '80%',
                    },
                  }}
                >
                  {link.label}
                </Button>
              ))} */}

              {/* Burial Insurance Dropdown */}
              <Box sx={{ position: 'relative' }}>
                <Button
                  onClick={(e) => handleMenuOpen('burialInsurance', e)}
                  sx={{
                    color: '#4B4F58',
                    fontWeight: '600',
                    fontSize: '14px',
                    padding: '8px 14px',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '6px',
                    transition: 'all 0.3s ease',
                    '&:hover': {
                      color: '#0170B9',
                      backgroundColor: 'rgba(1, 112, 185, 0.08)',
                      borderRadius: '4px',
                    },
                  }}
                >
                  Burial Insurance
                  <KeyboardArrowDownIcon 
                    sx={{ 
                      fontSize: '18px',
                      transform: Boolean(anchorEl.burialInsurance) ? 'rotate(180deg)' : 'rotate(0)',
                      transition: 'transform 0.3s ease',
                    }} 
                  />
                </Button>
                <Menu
                  anchorEl={anchorEl.burialInsurance}
                  open={Boolean(anchorEl.burialInsurance)}
                  onClose={() => handleMenuClose('burialInsurance')}
                  PaperProps={{
                    sx: {
                      boxShadow: '0 8px 32px rgba(0, 0, 0, 0.12)',
                      borderRadius: '8px',
                      marginTop: '8px',
                      minWidth: '280px',
                      '& .MuiMenuItem-root': {
                        padding: '12px 20px',
                        fontSize: '14px',
                        fontWeight: '500',
                        color: '#4B4F58',
                        transition: 'all 0.2s ease',
                        '&:hover': {
                          backgroundColor: '#f0f8ff',
                          color: '#0170B9',
                          paddingLeft: '24px',
                        },
                        '&::before': {
                          content: '""',
                          display: 'inline-block',
                          width: '4px',
                          height: '4px',
                          borderRadius: '50%',
                          backgroundColor: '#239F7D',
                          marginRight: '12px',
                          opacity: '0',
                          transition: 'opacity 0.2s ease',
                        },
                        '&:hover::before': {
                          opacity: '1',
                        },
                      },
                    },
                  }}
                >
                  {burialInsuranceMenu.map((item, idx) => (
                    <MenuItem
                      key={idx}
                      component={RouterLink}
                      to={item.path}
                      onClick={() => handleMenuClose('burialInsurance')}
                    >
                      {item.label}
                    </MenuItem>
                  ))}
                </Menu>
              </Box>

              {/* Cost of Burial Dropdown */}
              <Box sx={{ position: 'relative' }}>
                <Button
                  onClick={(e) => handleMenuOpen('costOfBurial', e)}
                  sx={{
                    color: '#4B4F58',
                    fontWeight: '600',
                    fontSize: '14px',
                    padding: '8px 14px',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '6px',
                    transition: 'all 0.3s ease',
                    '&:hover': {
                      color: '#0170B9',
                      backgroundColor: 'rgba(1, 112, 185, 0.08)',
                      borderRadius: '4px',
                    },
                  }}
                >
                  Cost of Burial
                  <KeyboardArrowDownIcon 
                    sx={{ 
                      fontSize: '18px',
                      transform: Boolean(anchorEl.costOfBurial) ? 'rotate(180deg)' : 'rotate(0)',
                      transition: 'transform 0.3s ease',
                    }} 
                  />
                </Button>
                <Menu
                  anchorEl={anchorEl.costOfBurial}
                  open={Boolean(anchorEl.costOfBurial)}
                  onClose={() => handleMenuClose('costOfBurial')}
                  PaperProps={{
                    sx: {
                      boxShadow: '0 8px 32px rgba(0, 0, 0, 0.12)',
                      borderRadius: '8px',
                      marginTop: '8px',
                      minWidth: '280px',
                      '& .MuiMenuItem-root': {
                        padding: '12px 20px',
                        fontSize: '14px',
                        fontWeight: '500',
                        color: '#4B4F58',
                        transition: 'all 0.2s ease',
                        '&:hover': {
                          backgroundColor: '#f0f8ff',
                          color: '#0170B9',
                          paddingLeft: '24px',
                        },
                        '&::before': {
                          content: '""',
                          display: 'inline-block',
                          width: '4px',
                          height: '4px',
                          borderRadius: '50%',
                          backgroundColor: '#239F7D',
                          marginRight: '12px',
                          opacity: '0',
                          transition: 'opacity 0.2s ease',
                        },
                        '&:hover::before': {
                          opacity: '1',
                        },
                      },
                    },
                  }}
                >
                  {costOfBurialMenu.map((item, idx) => (
                    <MenuItem
                      key={idx}
                      component={RouterLink}
                      to={item.path}
                      onClick={() => handleMenuClose('costOfBurial')}
                    >
                      {item.label}
                    </MenuItem>
                  ))}
                </Menu>
              </Box>

              {/* High-Risk Dropdown */}
              <Box sx={{ position: 'relative' }}>
                <Button
                  onClick={(e) => handleMenuOpen('highRisk', e)}
                  sx={{
                    color: '#4B4F58',
                    fontWeight: '600',
                    fontSize: '14px',
                    padding: '8px 14px',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '6px',
                    transition: 'all 0.3s ease',
                    '&:hover': {
                      color: '#0170B9',
                      backgroundColor: 'rgba(1, 112, 185, 0.08)',
                      borderRadius: '4px',
                    },
                  }}
                >
                  High-Risk
                  <KeyboardArrowDownIcon 
                    sx={{ 
                      fontSize: '18px',
                      transform: Boolean(anchorEl.highRisk) ? 'rotate(180deg)' : 'rotate(0)',
                      transition: 'transform 0.3s ease',
                    }} 
                  />
                </Button>
                <Menu
                  anchorEl={anchorEl.highRisk}
                  open={Boolean(anchorEl.highRisk)}
                  onClose={() => handleMenuClose('highRisk')}
                  PaperProps={{
                    sx: {
                      boxShadow: '0 8px 32px rgba(0, 0, 0, 0.12)',
                      borderRadius: '8px',
                      marginTop: '8px',
                      minWidth: '280px',
                      '& .MuiMenuItem-root': {
                        padding: '12px 20px',
                        fontSize: '14px',
                        fontWeight: '500',
                        color: '#4B4F58',
                        transition: 'all 0.2s ease',
                        '&:hover': {
                          backgroundColor: '#f0f8ff',
                          color: '#0170B9',
                          paddingLeft: '24px',
                        },
                        '&::before': {
                          content: '""',
                          display: 'inline-block',
                          width: '4px',
                          height: '4px',
                          borderRadius: '50%',
                          backgroundColor: '#239F7D',
                          marginRight: '12px',
                          opacity: '0',
                          transition: 'opacity 0.2s ease',
                        },
                        '&:hover::before': {
                          opacity: '1',
                        },
                      },
                    },
                  }}
                >
                  {highRiskMenu.map((item, idx) => (
                    <MenuItem
                      key={idx}
                      component={RouterLink}
                      to={item.path}
                      onClick={() => handleMenuClose('highRisk')}
                    >
                      {item.label}
                    </MenuItem>
                  ))}
                </Menu>
              </Box>

              {/* About Dropdown */}
              <Box sx={{ position: 'relative' }}>
                <Button
                  onClick={(e) => handleMenuOpen('about', e)}
                  sx={{
                    color: '#4B4F58',
                    fontWeight: '600',
                    fontSize: '14px',
                    padding: '8px 14px',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '6px',
                    transition: 'all 0.3s ease',
                    '&:hover': {
                      color: '#0170B9',
                      backgroundColor: 'rgba(1, 112, 185, 0.08)',
                      borderRadius: '4px',
                    },
                  }}
                >
                  About
                  <KeyboardArrowDownIcon 
                    sx={{ 
                      fontSize: '18px',
                      transform: Boolean(anchorEl.about) ? 'rotate(180deg)' : 'rotate(0)',
                      transition: 'transform 0.3s ease',
                    }} 
                  />
                </Button>
                <Menu
                  anchorEl={anchorEl.about}
                  open={Boolean(anchorEl.about)}
                  onClose={() => handleMenuClose('about')}
                  PaperProps={{
                    sx: {
                      boxShadow: '0 8px 32px rgba(0, 0, 0, 0.12)',
                      borderRadius: '8px',
                      marginTop: '8px',
                      minWidth: '280px',
                      '& .MuiMenuItem-root': {
                        padding: '12px 20px',
                        fontSize: '14px',
                        fontWeight: '500',
                        color: '#4B4F58',
                        transition: 'all 0.2s ease',
                        '&:hover': {
                          backgroundColor: '#f0f8ff',
                          color: '#0170B9',
                          paddingLeft: '24px',
                        },
                        '&::before': {
                          content: '""',
                          display: 'inline-block',
                          width: '4px',
                          height: '4px',
                          borderRadius: '50%',
                          backgroundColor: '#239F7D',
                          marginRight: '12px',
                          opacity: '0',
                          transition: 'opacity 0.2s ease',
                        },
                        '&:hover::before': {
                          opacity: '1',
                        },
                      },
                    },
                  }}
                >
                  {aboutMenu.map((item, idx) => (
                    <MenuItem
                      key={idx}
                      component={RouterLink}
                      to={item.path}
                      onClick={() => handleMenuClose('about')}
                    >
                      {item.label}
                    </MenuItem>
                  ))}
                </Menu>
              </Box>

              {/* Final Expense by State Dropdown */}
              <Box sx={{ position: 'relative' }}>
                <Button
                  onClick={(e) => handleMenuOpen('finalExpense', e)}
                  sx={{
                    color: '#4B4F58',
                    fontWeight: '600',
                    fontSize: '14px',
                    padding: '8px 14px',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '6px',
                    transition: 'all 0.3s ease',
                    '&:hover': {
                      color: '#0170B9',
                      backgroundColor: 'rgba(1, 112, 185, 0.08)',
                      borderRadius: '4px',
                    },
                  }}
                >
                  Final Expense
                  <KeyboardArrowDownIcon 
                    sx={{ 
                      fontSize: '18px',
                      transform: Boolean(anchorEl.finalExpense) ? 'rotate(180deg)' : 'rotate(0)',
                      transition: 'transform 0.3s ease',
                    }} 
                  />
                </Button>
                <Menu
                  anchorEl={anchorEl.finalExpense}
                  open={Boolean(anchorEl.finalExpense)}
                  onClose={() => handleMenuClose('finalExpense')}
                  PaperProps={{
                    sx: {
                      boxShadow: '0 8px 32px rgba(0, 0, 0, 0.12)',
                      borderRadius: '8px',
                      marginTop: '8px',
                      maxHeight: '500px',
                      overflowY: 'auto',
                      '& .MuiMenuItem-root': {
                        padding: '10px 20px',
                        fontSize: '13px',
                        fontWeight: '500',
                        color: '#4B4F58',
                        transition: 'all 0.2s ease',
                        '&:hover': {
                          backgroundColor: '#f0f8ff',
                          color: '#0170B9',
                          paddingLeft: '24px',
                        },
                        '&::before': {
                          content: '""',
                          display: 'inline-block',
                          width: '4px',
                          height: '4px',
                          borderRadius: '50%',
                          backgroundColor: '#239F7D',
                          marginRight: '10px',
                          opacity: '0',
                          transition: 'opacity 0.2s ease',
                        },
                        '&:hover::before': {
                          opacity: '1',
                        },
                      },
                    },
                  }}
                >
                  {statesMenu.map((item, idx) => (
                    <MenuItem
                      key={idx}
                      component={RouterLink}
                      to={item.path}
                      onClick={() => handleMenuClose('finalExpense')}
                    >
                      {item.label}
                    </MenuItem>
                  ))}
                </Menu>
              </Box>

              <Button
                component={RouterLink}
                to="/contact"
                sx={{
                  background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
                  color: '#FFFFFF',
                  marginLeft: '16px',
                  fontWeight: '700',
                  fontSize: '14px',
                  padding: '10px 28px',
                  borderRadius: '8px',
                  transition: 'all 0.3s ease',
                  boxShadow: '0 4px 16px rgba(1, 112, 185, 0.3)',
                  textTransform: 'none',
                  position: 'relative',
                  overflow: 'hidden',
                  zIndex: 0,
                  '&::before': {
                    content: '""',
                    position: 'absolute',
                    top: 0,
                    left: 0,
                    right: 0,
                    bottom: 0,
                    background: 'linear-gradient(135deg, #239F7D 0%, #0170B9 100%)',
                    opacity: 0,
                    transition: 'opacity 0.3s ease',
                    zIndex: -1,
                  },
                  '&:hover': {
                    boxShadow: '0 6px 20px rgba(35, 159, 125, 0.4)',
                    transform: 'translateY(-2px)',
                    '&::before': {
                      opacity: 1,
                    },
                  },
                }}
              >
                Contact Us
              </Button>
{/* 
              <Button
                variant="contained"
                sx={{
                  backgroundColor: '#FCDC00',
                  color: '#000',
                  marginLeft: '16px',
                  fontWeight: '700',
                  fontSize: '14px',
                  padding: '10px 24px',
                  borderRadius: '6px',
                  transition: 'all 0.3s ease',
                  boxShadow: '0 4px 12px rgba(252, 220, 0, 0.3)',
                  '&:hover': {
                    backgroundColor: '#E6C800',
                    boxShadow: '0 6px 16px rgba(252, 220, 0, 0.4)',
                    transform: 'translateY(-2px)',
                  },
                }}
              >
                Get A Quote
              </Button> */}
            </Box>
          )}

          {/* Mobile Menu Toggle */}
          {isMobile && (
            <IconButton
              onClick={handleDrawerToggle}
              sx={{ color: '#0170B9' }}
            >
              <MenuIcon />
            </IconButton>
          )}
        </Toolbar>
      </Container>

      {/* Mobile Drawer */}
      <Drawer
        anchor="right"
        open={drawerOpen}
        onClose={handleDrawerToggle}
      >
        {drawer}
      </Drawer>
    </AppBar>
  );
};

export default Navbar;
