import { createTheme } from '@mui/material/styles';

const theme = createTheme({
  palette: {
    primary: {
      main: '#0170B9', // Primary blue from original design
      light: '#6EC1E4',
      dark: '#00508F',
    },
    secondary: {
      main: '#239F7D', // Green accent
      light: '#61CE70',
      dark: '#006F51',
    },
    success: {
      main: '#61CE70',
    },
    warning: {
      main: '#FCDC00',
    },
    background: {
      default: '#F5F5F5',
      paper: '#FFFFFF',
    },
    text: {
      primary: '#4B4F58',
      secondary: '#7A7A7A',
    },
  },
  typography: {
    fontFamily: 'Roboto, -apple-system, BlinkMacSystemFont, Segoe UI, Oxygen-Sans, Ubuntu, Cantarell, Helvetica Neue, sans-serif',
    h1: {
      fontSize: '2.67rem',
      fontWeight: 600,
      lineHeight: 1.4,
      color: '#3a3a3a',
    },
    h2: {
      fontSize: '2.13rem',
      fontWeight: 600,
      lineHeight: 1.3,
      color: '#3a3a3a',
    },
    h3: {
      fontSize: '1.73rem',
      fontWeight: 600,
      lineHeight: 1.3,
      color: '#3a3a3a',
    },
    body1: {
      fontSize: '1rem',
      lineHeight: 1.65,
      color: '#4B4F58',
    },
    button: {
      textTransform: 'capitalize',
      fontWeight: 500,
    },
  },
  components: {
    MuiButton: {
      styleOverrides: {
        root: {
          borderRadius: '30px',
          padding: '10px 40px',
          fontSize: '1rem',
          '&:hover': {
            boxShadow: '0px 0px 30px rgba(0, 0, 0, 0.1)',
          },
        },
        contained: {
          backgroundColor: '#239F7D',
          color: '#FFFFFF',
          '&:hover': {
            backgroundColor: '#006F51',
          },
        },
      },
    },
    MuiAppBar: {
      styleOverrides: {
        root: {
          backgroundColor: '#FFFFFF',
          color: '#4B4F58',
          boxShadow: '0px 2px 4px rgba(0, 0, 0, 0.1)',
        },
      },
    },
    MuiCard: {
      styleOverrides: {
        root: {
          borderRadius: '15px',
          boxShadow: '0px 0px 20px rgba(0, 0, 0, 0.05)',
          transition: 'all 0.3s ease',
          '&:hover': {
            boxShadow: '0px 0px 30px rgba(0, 0, 0, 0.15)',
            transform: 'translateY(-5px)',
          },
        },
      },
    },
  },
});

export default theme;
