import React, { useState, useEffect } from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, IconButton } from '@mui/material';
import { ArrowBackIos, ArrowForwardIos } from '@mui/icons-material';

const GivingBack = () => {
  const [currentSlide, setCurrentSlide] = useState(0);

  const donationImages = [
    {
      src: 'https://senior-lifeservices.com/wp-content/uploads/2020/09/20170604_.jpg',
      alt: '20170604_'
    },
    {
      src: 'https://senior-lifeservices.com/wp-content/uploads/2020/09/BRANDON-WILKERSON.jpg',
      alt: 'BRANDON-WILKERSON'
    },
    {
      src: 'https://senior-lifeservices.com/wp-content/uploads/2020/09/DON-SCOTT-SKY-RANCH.jpg',
      alt: 'DON-SCOTT-SKY-RANCH'
    },
    {
      src: 'https://senior-lifeservices.com/wp-content/uploads/2020/09/FullSizeRender-1-1024x530-1.jpg',
      alt: 'FullSizeRender-1-1024x530'
    },
    {
      src: 'https://senior-lifeservices.com/wp-content/uploads/2020/09/IMG_0256.jpg',
      alt: 'IMG_0256'
    },
    {
      src: 'https://senior-lifeservices.com/wp-content/uploads/2020/09/IMG_2756.jpg',
      alt: 'IMG_2756'
    },
    {
      src: 'https://senior-lifeservices.com/wp-content/uploads/2020/09/unnamed-2.jpg',
      alt: 'unnamed-2'
    },
    {
      src: 'https://senior-lifeservices.com/wp-content/uploads/2020/09/unnamed-3.jpg',
      alt: 'unnamed-3'
    },
    {
      src: 'https://senior-lifeservices.com/wp-content/uploads/2020/09/unnamed-4.jpg',
      alt: 'unnamed-4'
    },
    {
      src: 'https://senior-lifeservices.com/wp-content/uploads/2020/09/unnamed-5.jpg',
      alt: 'unnamed-5'
    },
    {
      src: 'https://senior-lifeservices.com/wp-content/uploads/2020/09/unnamed-6.jpg',
      alt: 'unnamed-6'
    },
    {
      src: 'https://senior-lifeservices.com/wp-content/uploads/2020/09/unnamed-7.jpg',
      alt: 'unnamed-7'
    },
    {
      src: 'https://senior-lifeservices.com/wp-content/uploads/2020/09/unnamed-1024x768-1.jpg',
      alt: 'unnamed-1024x768'
    }
  ];

  // Auto-play slider
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % donationImages.length);
    }, 2500); // Change slide every 2.5 seconds

    return () => clearInterval(interval);
  }, [donationImages.length]);

  const handlePrevSlide = () => {
    setCurrentSlide((prev) => (prev - 1 + donationImages.length) % donationImages.length);
  };

  const handleNextSlide = () => {
    setCurrentSlide((prev) => (prev + 1) % donationImages.length);
  };

  return (
    <Box sx={{ width: '100%' }}>
      {/* Main Content */}
      <Container sx={{ py: 6 }}>
        <Grid container spacing={4}>
          <Grid item xs={12}>
            <Card sx={{ boxShadow: 3, p: { xs: 3, md: 4 } }}>
              <CardContent>
                <Typography 
                  variant="h2" 
                  component="h1"
                  sx={{ 
                    fontWeight: 'bold', 
                    mb: 3, 
                    color: '#0170B9'
                  }}
                >
                  Giving Back
                </Typography>

                <Typography 
                  variant="body1" 
                  paragraph 
                  sx={{ fontSize: '1.05rem', lineHeight: 1.8, mb: 3 }}
                >
                  During the last ten years, we have enjoyed explosive growth within our company. We have an army of agents that are earning more now than they ever have in their lives. We are both humbled and grateful for our tremendous success, and honored that we are continuing to grow with lives being changed along the way.
                </Typography>

                <Typography 
                  variant="body1" 
                  paragraph 
                  sx={{ fontSize: '1.05rem', lineHeight: 1.8, mb: 3 }}
                >
                  Because we have been so fortunate, in 2012 we decided to form an outreach program to "Give Back" to the communities we serve. There are many people suffering in poverty and in need of help in the communities we serve, and we are proud to be able to contribute financially to help those who need help the most.
                </Typography>

                <Typography 
                  variant="body1" 
                  paragraph 
                  sx={{ fontSize: '1.05rem', lineHeight: 1.8, mb: 3 }}
                >
                  Since 2012 we have donated to more than 50 community-based charities in more than 15 states. Our donations currently exceed $100,000 and are growing.
                </Typography>

                <Typography 
                  variant="body1" 
                  sx={{ fontSize: '1.05rem', lineHeight: 1.8, mb: 4 }}
                >
                  Please view the photos of donations from the past and expect to see this program grow to new heights in the future.
                </Typography>
              </CardContent>
            </Card>
          </Grid>

          {/* Donation Photos Slider */}
          <Grid item xs={12}>
            <Card sx={{ boxShadow: 3, p: { xs: 3, md: 4 } }}>
              <CardContent>
                <Typography 
                  variant="h4" 
                  sx={{ 
                    fontWeight: 'bold', 
                    mb: 4, 
                    color: '#0170B9',
                    textAlign: 'center'
                  }}
                >
                  Our Community Impact
                </Typography>

                {/* Image Slider */}
                <Box 
                  sx={{ 
                    position: 'relative',
                    width: '100%',
                    maxWidth: '900px',
                    margin: '0 auto',
                    overflow: 'hidden',
                    borderRadius: 2,
                    boxShadow: 3
                  }}
                >
                  {/* Images */}
                  <Box
                    sx={{
                      display: 'flex',
                      transition: 'transform 0.5s ease-in-out',
                      transform: `translateX(-${currentSlide * 100}%)`
                    }}
                  >
                    {donationImages.map((image, index) => (
                      <Box
                        key={index}
                        component="img"
                        src={image.src}
                        alt={image.alt}
                        sx={{
                          width: '100%',
                          height: 'auto',
                          flexShrink: 0,
                          objectFit: 'cover'
                        }}
                      />
                    ))}
                  </Box>

                  {/* Previous Button */}
                  <IconButton
                    onClick={handlePrevSlide}
                    sx={{
                      position: 'absolute',
                      left: 16,
                      top: '50%',
                      transform: 'translateY(-50%)',
                      backgroundColor: 'rgba(255, 255, 255, 0.8)',
                      '&:hover': {
                        backgroundColor: 'rgba(255, 255, 255, 0.95)'
                      },
                      boxShadow: 2
                    }}
                  >
                    <ArrowBackIos sx={{ ml: 1 }} />
                  </IconButton>

                  {/* Next Button */}
                  <IconButton
                    onClick={handleNextSlide}
                    sx={{
                      position: 'absolute',
                      right: 16,
                      top: '50%',
                      transform: 'translateY(-50%)',
                      backgroundColor: 'rgba(255, 255, 255, 0.8)',
                      '&:hover': {
                        backgroundColor: 'rgba(255, 255, 255, 0.95)'
                      },
                      boxShadow: 2
                    }}
                  >
                    <ArrowForwardIos />
                  </IconButton>

                  {/* Dots Indicator */}
                  <Box
                    sx={{
                      position: 'absolute',
                      bottom: 16,
                      left: '50%',
                      transform: 'translateX(-50%)',
                      display: 'flex',
                      gap: 1
                    }}
                  >
                    {donationImages.map((_, index) => (
                      <Box
                        key={index}
                        onClick={() => setCurrentSlide(index)}
                        sx={{
                          width: 10,
                          height: 10,
                          borderRadius: '50%',
                          backgroundColor: currentSlide === index ? '#239F7D' : 'rgba(255, 255, 255, 0.6)',
                          cursor: 'pointer',
                          transition: 'all 0.3s ease',
                          '&:hover': {
                            backgroundColor: currentSlide === index ? '#239F7D' : 'rgba(255, 255, 255, 0.9)'
                          }
                        }}
                      />
                    ))}
                  </Box>
                </Box>
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      </Container>
    </Box>
  );
};

export default GivingBack;
