import React, { useState, useRef, useEffect } from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button } from '@mui/material';
import { Link as RouterLink, useNavigate } from 'react-router-dom';
import USAMap from 'react-usa-map';

const states = [
	{ label: 'Alabama', path: '/final-expense/alabama' },
	{ label: 'Alaska', path: '/final-expense/alaska' },
	{ label: 'Arizona', path: '/final-expense/arizona' },
	{ label: 'Arkansas', path: '/final-expense/arkansas' },
	{ label: 'California', path: '/final-expense/california' },
	{ label: 'Colorado', path: '/final-expense/colorado' },
	{ label: 'Connecticut', path: '/final-expense/connecticut' },
	{ label: 'Delaware', path: '/final-expense/delaware' },
	{ label: 'Florida', path: '/final-expense/florida' },
	{ label: 'Georgia', path: '/final-expense/georgia' },
	{ label: 'Hawaii', path: '/final-expense/hawaii' },
	{ label: 'Idaho', path: '/final-expense/idaho' },
	{ label: 'Illinois', path: '/final-expense/illinois' },
	{ label: 'Indiana', path: '/final-expense/indiana' },
	{ label: 'Iowa', path: '/final-expense/iowa' },
	{ label: 'Kansas', path: '/final-expense/kansas' },
	{ label: 'Kentucky', path: '/final-expense/kentucky' },
	{ label: 'Louisiana', path: '/final-expense/louisiana' },
	{ label: 'Maine', path: '/final-expense/maine' },
	{ label: 'Maryland', path: '/final-expense/maryland' },
	{ label: 'Massachusetts', path: '/final-expense/massachusetts' },
	{ label: 'Michigan', path: '/final-expense/michigan' },
	{ label: 'Minnesota', path: '/final-expense/minnesota' },
	{ label: 'Mississippi', path: '/final-expense/mississippi' },
	{ label: 'Missouri', path: '/final-expense/missouri' },
	{ label: 'Montana', path: '/final-expense/montana' },
	{ label: 'Nebraska', path: '/final-expense/nebraska' },
	{ label: 'Nevada', path: '/final-expense/nevada' },
	{ label: 'New Hampshire', path: '/final-expense/new-hampshire' },
	{ label: 'New Jersey', path: '/final-expense/new-jersey' },
	{ label: 'New Mexico', path: '/final-expense/new-mexico' },
	{ label: 'New York', path: '/final-expense/new-york' },
	{ label: 'North Carolina', path: '/final-expense/north-carolina' },
	{ label: 'North Dakota', path: '/final-expense/north-dakota' },
	{ label: 'Ohio', path: '/final-expense/ohio' },
	{ label: 'Oklahoma', path: '/final-expense/oklahoma' },
	{ label: 'Oregon', path: '/final-expense/oregon' },
	{ label: 'Pennsylvania', path: '/final-expense/pennsylvania' },
	{ label: 'Rhode Island', path: '/final-expense/rhode-island' },
	{ label: 'South Carolina', path: '/final-expense/south-carolina' },
	{ label: 'South Dakota', path: '/final-expense/south-dakota' },
	{ label: 'Tennessee', path: '/final-expense/tennessee' },
	{ label: 'Texas', path: '/final-expense/texas' },
	{ label: 'Utah', path: '/final-expense/utah' },
	{ label: 'Vermont', path: '/final-expense/vermont' },
	{ label: 'Virginia', path: '/final-expense/virginia' },
	{ label: 'Washington', path: '/final-expense/washington' },
	{ label: 'West Virginia', path: '/final-expense/west-virginia' },
	{ label: 'Wisconsin', path: '/final-expense/wisconsin' },
	{ label: 'Wyoming', path: '/final-expense/wyoming' },
];

const stateAbbrevMap = {
	AL: '/final-expense/alabama', AK: '/final-expense/alaska', AZ: '/final-expense/arizona', AR: '/final-expense/arkansas', CA: '/final-expense/california', CO: '/final-expense/colorado', CT: '/final-expense/connecticut', DE: '/final-expense/delaware', FL: '/final-expense/florida', GA: '/final-expense/georgia', HI: '/final-expense/hawaii', ID: '/final-expense/idaho', IL: '/final-expense/illinois', IN: '/final-expense/indiana', IA: '/final-expense/iowa', KS: '/final-expense/kansas', KY: '/final-expense/kentucky', LA: '/final-expense/louisiana', ME: '/final-expense/maine', MD: '/final-expense/maryland', MA: '/final-expense/massachusetts', MI: '/final-expense/michigan', MN: '/final-expense/minnesota', MS: '/final-expense/mississippi', MO: '/final-expense/missouri', MT: '/final-expense/montana', NE: '/final-expense/nebraska', NV: '/final-expense/nevada', NH: '/final-expense/new-hampshire', NJ: '/final-expense/new-jersey', NM: '/final-expense/new-mexico', NY: '/final-expense/new-york', NC: '/final-expense/north-carolina', ND: '/final-expense/north-dakota', OH: '/final-expense/ohio', OK: '/final-expense/oklahoma', OR: '/final-expense/oregon', PA: '/final-expense/pennsylvania', RI: '/final-expense/rhode-island', SC: '/final-expense/south-carolina', SD: '/final-expense/south-dakota', TN: '/final-expense/tennessee', TX: '/final-expense/texas', UT: '/final-expense/utah', VT: '/final-expense/vermont', VA: '/final-expense/virginia', WA: '/final-expense/washington', WV: '/final-expense/west-virginia', WI: '/final-expense/wisconsin', WY: '/final-expense/wyoming'
};

const FinalExpensebystate = () => {
	const navigate = useNavigate();
	const [hovered, setHovered] = useState(null);
	const [tooltipPos, setTooltipPos] = useState({ x: 0, y: 0 });
	const mapContainerRef = useRef(null);

	const handleMapClick = (event) => {
		const abbr = (event && event.target && event.target.dataset && event.target.dataset.name) || event;
		if (!abbr) return;
		const key = typeof abbr === 'string' ? abbr.toUpperCase() : String(abbr).toUpperCase();
		const path = stateAbbrevMap[key];
		if (path) navigate(path);
	};

	const getLabelForAbbr = (abbr) => {
		const key = (abbr || '').toUpperCase();
		const path = stateAbbrevMap[key];
		if (!path) return key;
		const st = states.find(s => s.path === path);
		return st ? st.label : key;
	};

	const handleMapMouseMove = (e) => {
		const target = e.target;
		const abbr = (target && target.dataset && target.dataset.name) || target.id || null;
		if (abbr) {
			const key = String(abbr).toUpperCase();
			if (stateAbbrevMap[key]) {
				setHovered(key);
				const rect = mapContainerRef.current?.getBoundingClientRect() || { left: 0, top: 0 };
				setTooltipPos({ x: e.clientX - rect.left + 12, y: e.clientY - rect.top + 12 });
				return;
			}
		}
		setHovered(null);
	};

	const handleMapMouseLeave = () => setHovered(null);

	// Remove any <title> elements inside the map SVG to prevent the browser's default tooltip
	useEffect(() => {
		const removeTitles = () => {
			try {
				const node = mapContainerRef.current;
				if (!node) return;
				const titles = node.querySelectorAll('title');
				titles.forEach(t => t.remove());
			} catch (e) {
				// ignore
			}
		};

		removeTitles();
		const observer = new MutationObserver(() => removeTitles());
		if (mapContainerRef.current) {
			observer.observe(mapContainerRef.current, { childList: true, subtree: true });
		}
		return () => observer.disconnect();
	}, []);

	// build a customize object for react-usa-map so fills update when `hovered` changes
	const mapCustomize = React.useMemo(() => {
		const obj = {};
		Object.keys(stateAbbrevMap).forEach((abbr) => {
			obj[abbr] = {
				fill: abbr === hovered ? '#0170B9' : '#239F7D',
				stroke: '#ffffff',
				// react-usa-map uses 'strokeWidth' as 'strokeWidth' when rendering props onto path
				strokeWidth: 1,
			};
		});
		
		return obj;
	}, [hovered]);

	return (
		<Box sx={{ width: '100%' }}>
			<Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 10,
          textAlign: 'center',
          position: 'relative',
          overflow: 'hidden',
          '&::before': {
            content: '""',
            position: 'absolute',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: 'radial-gradient(circle at 20% 50%, rgba(255,255,255,0.1) 0%, transparent 50%)',
            pointerEvents: 'none',
          }
        }}
      >
        <Container sx={{ position: 'relative', zIndex: 1 }}>
          <Typography 
            variant="h1" 
            sx={{ 
              fontWeight: 900,
              mb: 2,
              fontSize: { xs: '2.5rem', sm: '3.5rem', md: '4rem' },
              letterSpacing: '-1px',
              background: 'linear-gradient(135deg, #FFFFFF 0%, #FFFACD 50%, #FFFFFF 100%)',
              backgroundClip: 'text',
              WebkitBackgroundClip: 'text',
              WebkitTextFillColor: 'transparent',
              textShadow: '2px 2px 4px rgba(0,0,0,0.2)',
              filter: 'drop-shadow(2px 2px 4px rgba(0,0,0,0.15))',
            }}
          >
            Final Expense Insurance in All States
          </Typography>
          <Typography 
            variant="h5" 
            sx={{ 
              fontWeight: 400,
              fontSize: { xs: '1rem', md: '1.25rem' },
              color: '#FFFACD',
              mb: 1,
              letterSpacing: '1px',
              fontStyle: 'italic',
            }}
          >
            Protect Your Family, Plan Your Future
          </Typography>
          <Box
            sx={{
              height: '3px',
              width: '60px',
              background: 'linear-gradient(90deg, #FFFACD 0%, transparent 100%)',
              margin: '0 auto',
              mt: 2,
            }}
          />
        </Container>
      </Box>


			<Container sx={{ py: 6 }}>
				<Box sx={{ mb: 4, textAlign: 'center' }}>
					<Typography variant="h6" sx={{ mb: 2 }}>Click a state on the map to view details</Typography>
					<Box sx={{ maxWidth: 1000, margin: '0 auto', position: 'relative' }} ref={mapContainerRef} onMouseMove={handleMapMouseMove} onMouseLeave={handleMapMouseLeave}>
						<style>{`\n\t\t\t\t\t.usa-map { width: 100%; height: auto; }\n\t\t\t\t\t.usa-map path { fill: #239F7D; stroke: #ffffff; stroke-width: 1; transition: fill 150ms ease, transform 120ms ease; }\n\t\t\t\t\t.usa-map path:hover { fill: #0170B9; cursor: pointer; transform: scale(1.03); }\n\t\t\t\t\t.usa-map path#CO { fill: #FCDC00; }\n\t\t\t\t\t`}</style>
						<USAMap className="usa-map" onClick={handleMapClick} customize={mapCustomize} />

						{hovered && (
							<Box sx={{ position: 'absolute', pointerEvents: 'none' }} style={{ left: tooltipPos.x, top: tooltipPos.y }}>
								<Box sx={{ backgroundColor: 'rgba(255, 255, 255, 0.8)', color: '#000000ff', px: 1.5, py: 0.6, borderRadius: 1, boxShadow: 3 }}>
									<Typography variant="subtitle1" sx={{ fontWeight: 'bold', fontSize: '1rem' }}>{getLabelForAbbr(hovered)}</Typography>
								</Box>
							</Box>
						)}
					</Box>
				</Box>

				<Grid container spacing={3}>
					{states.map((s) => (
						<Grid item xs={12} sm={6} md={4} lg={3} key={s.path}>
							<Card sx={{ height: '100%', display: 'flex', flexDirection: 'column', boxShadow: 3 }} component={RouterLink} to={s.path}>
								<CardContent sx={{ p: 3, flexGrow: 1 }}>
									<Typography variant="h6" sx={{ fontWeight: 'bold', color: '#0170B9' }}>{s.label}</Typography>
									<Typography variant="body2" sx={{ mt: 1, color: 'text.secondary' }}>Learn about final expense insurance and typical costs in {s.label}.</Typography>
								</CardContent>
								<Box sx={{ p: 2 }}>
									<Button component={RouterLink} to={s.path} variant="contained" fullWidth sx={{ backgroundColor: '#239F7D', color: '#000', '&:hover': { backgroundColor: '#239F7D' } }}>View {s.label}</Button>
								</Box>
							</Card>
						</Grid>
					))}
				</Grid>
			</Container>
		</Box>
	);
};

export default FinalExpensebystate;